import json, math, sys
from collections import defaultdict
from cost_model import CostModel, align, HEADS, HIDDEN
cm=CostModel(64); c=cm.c
def load(b): return [json.loads(l) for l in open(f'../input_data/requests_bucket_{b}.jsonl')]
def Fcost(S,G):
    A,B=c.Kd_attn, c.Kd_mlp*HIDDEN
    return A*cm._sum_sq_arith(S,G)+B*(G*S+G*(G-1)/2)
def Flat(S,G):
    A,B=c.Td_attn,c.Td_mlp*HIDDEN
    return A*cm._sum_sq_arith(S,G)+B*(G*S+G*(G-1)/2)
class B:
    __slots__=('n','S','G','pad','dcost','prefmax','lat','ids','gsum')
    def __init__(self,G,S,ids,prefs):
        self.n=len(ids); self.S=S; self.G=G; self.ids=ids; self.gsum=G*len(ids)
        self.pad=self.n*G-self.gsum; self.dcost=self.n*Fcost(S,G)
        self.prefmax=max(prefs); self.lat=self.prefmax+Flat(S,G)+c.Tbatch_overhead_ms
def merge(a,o):
    nb=B.__new__(B); nb.n=a.n+o.n; nb.S=max(a.S,o.S); nb.G=max(a.G,o.G)
    nb.ids=a.ids+o.ids; nb.gsum=a.gsum+o.gsum; nb.pad=nb.n*nb.G-nb.gsum
    nb.dcost=nb.n*Fcost(nb.S,nb.G); nb.prefmax=max(a.prefmax,o.prefmax)
    nb.lat=nb.prefmax+Flat(nb.S,nb.G)+c.Tbatch_overhead_ms; return nb
def initial(rs):
    d=defaultdict(list)
    for r in rs: d[(align(r['prompt_len'],64),r['gen_len'])].append(r)
    prefs={r['request_id']:cm._prefill_lat(r['prompt_len']) for r in rs}
    out=[]
    for (S,G),grp in d.items():
        ids=[r['request_id'] for r in grp]; out.append(B(G,S,ids,[prefs[i] for i in ids]))
    return out,prefs
def metrics(bs,rs):
    real=sum(r['prompt_len']+r['gen_len'] for r in rs)
    padp=sum(align(r['prompt_len'],64)-r['prompt_len'] for r in rs)
    pad=padp+sum(b.pad for b in bs)
    prefcost=sum(cm._prefill_cost(r['prompt_len']) for r in rs)
    smax=max(align(r['prompt_len'],64) for r in rs)
    compile=c.Kshape_attn*(smax**2)+c.Kshape_mlp*(smax*HIDDEN)
    cost=prefcost+sum(b.dcost for b in bs)+c.Kbatch_overhead_cost*len(bs)+compile
    lats=[]
    for b in bs: lats += [b.lat]*b.n
    lats.sort(); k=max(0,min(len(lats)-1,int(math.ceil(.95*len(lats))-1)))
    return dict(cost=cost,pad_ratio=pad/real,pad=pad,real=real,p95=lats[k],seq=sum(b.lat for b in bs),B=len(bs))
def run(bucket, mode, budgets):
    rs=load(bucket); bs,prefs=initial(rs)
    Cmax,Pmax,seqtarget,p95target,padmax=budgets
    it=0
    while bs:
        m=metrics(bs,rs)
        if m['seq']<=seqtarget: break
        if m['cost']>Cmax or m['pad_ratio']>padmax or m['p95']>p95target: break
        best=None; n=len(bs)
        for i in range(n):
            a=bs[i]
            for j in range(i+1,n):
                b=bs[j]; nb=merge(a,b)
                dpad=nb.pad-a.pad-b.pad
                dcost=nb.dcost-a.dcost-b.dcost-c.Kbatch_overhead_cost
                dseq=nb.lat-a.lat-b.lat
                if dseq>=0: continue
                if mode=='pad': score=(dpad+1e-9)/(-dseq)
                elif mode=='cost': score=(dcost+1e-9)/(-dseq)
                elif mode=='mix': score=((dpad/Pmax)+(dcost/Cmax)*0.3)/(-dseq)
                elif mode=='lat_sq': score=(dpad+ (dcost/Cmax)*3000)/(-dseq)
                if best is None or score<best[0]: best=(score,i,j,nb)
        if best is None: break
        _,i,j,nb=best
        bs=[b for k,b in enumerate(bs) if k not in (i,j)]+[nb]
        it+=1
        if it%50==0:
            m=metrics(bs,rs); print(' it',it,'B',m['B'],'cost %.3e'%m['cost'],'pad %.4f'%m['pad_ratio'],'seq %.3e'%m['seq'],'p95 %.3e'%m['p95'],flush=True)
    return bs,metrics(bs,rs)
if __name__=='__main__':
    bucket=int(sys.argv[1]); mode=sys.argv[2]
    if bucket==1: budgets=(2.98e11,0.0548,2.45e8,2.09e6,0.0548)
    else: budgets=(4.75e10,0.149,2.9e7,2.08e5,0.149)
    bs,m=run(bucket,mode,budgets)
    print('RESULT',bucket,mode,m)
